    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'NET14');
  assert.equal(invoice.dueDate, '2026-10-21');
});

test('invoiceTotals includes voucher field', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.voucher, 0);
});

test('applyVoucher adds a voucher to a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r.value;

  const result = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SUMMER20');
  assert.equal(result.value.voucher.amount, 5000);
});

test('applyVoucher reduces the total by voucher amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
