  const beforeVoucher = invoiceTotals(invoice);
  const withVoucher = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 }).value;
  const afterVoucher = invoiceTotals(withVoucher);

  assert.equal(beforeVoucher.total - afterVoucher.total, 5000);
});

test('applyVoucher reports NOT_DRAFT for non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r.value;
  const issued = issueInvoice(invoice, []).value;

  const result = applyVoucher(issued, { code: 'SUMMER20', amount: 5000 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher reports VOUCHER_EXISTS when one already applied', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r.value;

  const first = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 }).value;
  const result = applyVoucher(first, { code: 'WINTER10', amount: 3000 });

  assert.deepEqual(result, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher reports AMOUNT_INVALID for non-positive amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r.value;

  const result1 = applyVoucher(invoice, { code: 'SUMMER20', amount: 0 });
  assert.deepEqual(result1, { ok: false, error: 'AMOUNT_INVALID' });

  const result2 = applyVoucher(invoice, { code: 'SUMMER20', amount: -1000 });
  assert.deepEqual(result2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher reports AMOUNT_INVALID for non-integer amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r.value;

  const result = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000.50 });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r.value;

  const before = JSON.stringify(invoice);
  applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 });
  const after = JSON.stringify(invoice);

  assert.equal(before, after);
});

test('invoiceTotals with voucher subtracts from total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = r.value;
  const withVoucher = applyVoucher(invoice, { code: 'SUMMER20', amount: 10000 }).value;

  const totals = invoiceTotals(withVoucher);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

