/**
 * Calculate the subtotal, discount, VAT, voucher, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    voucher: Math.max(0, voucher),
    total,
  };
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a valid date in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount percent must be a number from 0 to 100.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NO_LINES: 'An invoice must have at least one line.',
  NOT_DRAFT: 'Can only edit invoices with draft status.',
  NOT_ISSUED: 'Can only record payments on issued or partially paid invoices.',
  OVERPAYMENT: 'Payment amount exceeds the balance due.',
  QTY_INVALID: 'Line quantity must be a positive integer.',
  TERMS_INVALID: 'Payment terms must be NET14, NET30, or EOM.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  VOUCHER_EXISTS: 'An invoice can only have one voucher.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}
